assertions.document:
property p_read_data_latency;
  @(posedge clk) disable iff (!rst_n)
  (!we) |=> (rdata == $past(mem[addr]));
endproperty
a_read_data: assert property (p_read_data_latency)
  else $error("SVA ERROR: Synchronous read latency violation! Expected: %h, Actual: %h", $past(mem[addr]), rdata);

property p_no_x_on_read;
  @(posedge clk) disable iff (!rst_n)
  (!we) |=> (!$isunknown(rdata));
endproperty
a_no_x_on_read: assert property (p_no_x_on_read)
  else $error("SVA ERROR: Unknowns (X/Z) detected on rdata output!");

property p_axi_valid_stable;
  @(posedge clk) disable iff (!rst_n)
  (valid && !ready) |=> (valid && $stable(data));
endproperty
a_axi_valid_stable: assert property (p_axi_valid_stable)
  else $error("SVA ERROR: AXI VALID deasserted or DATA changed before READY handshake!");

property p_apb_addr_stable;
  @(posedge clk) disable iff (!rst_n)
  (psel && penable && !pready) |=> $stable(paddr);
endproperty
a_apb_addr_stable: assert property (p_apb_addr_stable)
  else $error("SVA ERROR: APB PADDR changed during ACCESS wait states!");

property p_fifo_no_overflow;
  @(posedge clk) disable iff (!rst_n)
  (full && wr_en) |-> $error("SVA ERROR: FIFO write attempted while full!");
endproperty
a_fifo_no_overflow: assert property (p_fifo_no_overflow);
